<?php
namespace Database\Seeders;use App\Models\{CorporateAccount,EventVenue,Property,TravelAgent};use Illuminate\Database\Seeder;
class HotelSalesSeeder extends Seeder{public function run():void{foreach(Property::all() as $p){CorporateAccount::firstOrCreate(['property_id'=>$p->id,'code'=>'CORP-DEMO'],['name'=>'Demo Corporate Client','credit_limit'=>5000000,'credit_days'=>30,'status'=>'active']);TravelAgent::firstOrCreate(['property_id'=>$p->id,'code'=>'AGT-DEMO'],['name'=>'Demo Travel Agent','commission_percent'=>10,'credit_limit'=>3000000,'credit_days'=>14,'status'=>'active']);EventVenue::firstOrCreate(['property_id'=>$p->id,'code'=>'CONF-A'],['name'=>'Conference Hall A','capacity'=>120,'base_rate'=>800000,'status'=>'active']);EventVenue::firstOrCreate(['property_id'=>$p->id,'code'=>'BOARD'],['name'=>'Boardroom','capacity'=>20,'base_rate'=>250000,'status'=>'active']);}}}
